-- Fix search_path on update_updated_at
CREATE OR REPLACE FUNCTION public.update_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;

-- Fix search_path on generate_order_number
CREATE OR REPLACE FUNCTION public.generate_order_number()
RETURNS TEXT
LANGUAGE plpgsql
SET search_path = public
AS $$
DECLARE
  new_number TEXT;
  counter INTEGER;
BEGIN
  SELECT COUNT(*) + 1 INTO counter FROM public.orders;
  new_number := 'OW3D-' || LPAD(counter::TEXT, 5, '0');
  RETURN new_number;
END;
$$;

-- Create a proper sequence for order numbers
CREATE SEQUENCE IF NOT EXISTS public.order_number_seq START WITH 1 INCREMENT BY 1;

-- Set sequence to current max
SELECT setval('public.order_number_seq', COALESCE((
  SELECT MAX(CAST(REPLACE(order_number, 'OW3D-', '') AS INTEGER)) FROM public.orders
), 0));

-- Replace the function with a sequence-based one (no duplicates possible)
CREATE OR REPLACE FUNCTION public.generate_order_number()
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  new_number TEXT;
BEGIN
  new_number := 'OW3D-' || LPAD(nextval('public.order_number_seq')::TEXT, 5, '0');
  RETURN new_number;
END;
$function$;

CREATE TABLE public.exported_orders (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  order_id uuid NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,
  order_number text NOT NULL,
  download_url text NOT NULL,
  completed_at timestamp with time zone,
  created_at timestamp with time zone DEFAULT now(),
  UNIQUE(order_id)
);

ALTER TABLE public.exported_orders ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Admins can do everything with exported_orders"
ON public.exported_orders FOR ALL TO authenticated
USING (has_role(auth.uid(), 'admin'::app_role));

-- Customer email preferences, idempotent welcome messages, campaign audit data,
-- and safe claiming of admin-created orders.

ALTER TABLE public.profiles
  ADD COLUMN IF NOT EXISTS newsletter_subscribed boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS account_welcome_email_claimed_at timestamptz,
  ADD COLUMN IF NOT EXISTS account_welcome_email_sent_at timestamptz;

ALTER TABLE public.newsletter_subscriptions
  ADD COLUMN IF NOT EXISTS user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS welcome_email_claimed_at timestamptz,
  ADD COLUMN IF NOT EXISTS welcome_email_sent_at timestamptz;

ALTER TABLE public.newsletter_subscriptions
  DROP CONSTRAINT IF EXISTS newsletter_subscriptions_source_allowed;
ALTER TABLE public.newsletter_subscriptions
  ADD CONSTRAINT newsletter_subscriptions_source_allowed
  CHECK (source IN ('popup', 'footer', 'website', 'profile'));

CREATE UNIQUE INDEX IF NOT EXISTS newsletter_subscriptions_user_id_unique
  ON public.newsletter_subscriptions (user_id)
  WHERE user_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_orders_user_id
  ON public.orders (user_id)
  WHERE user_id IS NOT NULL;

REVOKE ALL ON FUNCTION public.subscribe_to_newsletter(text, text)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.subscribe_to_newsletter(text, text) TO service_role;

-- Link existing newsletter rows to matching profiles without changing consent.
UPDATE public.newsletter_subscriptions AS subscription
SET user_id = profile.user_id
FROM public.profiles AS profile
WHERE subscription.user_id IS NULL
  AND lower(subscription.email) = lower(profile.email)
  AND NOT EXISTS (
    SELECT 1
    FROM public.newsletter_subscriptions AS linked
    WHERE linked.user_id = profile.user_id
  );

UPDATE public.profiles AS profile
SET newsletter_subscribed = subscription.active
FROM public.newsletter_subscriptions AS subscription
WHERE subscription.user_id = profile.user_id
  AND profile.newsletter_subscribed IS DISTINCT FROM subscription.active;

CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE existing_subscription_active boolean := false;
BEGIN
  SELECT active
  INTO existing_subscription_active
  FROM public.newsletter_subscriptions
  WHERE lower(email) = lower(coalesce(NEW.email, ''))
  LIMIT 1;

  INSERT INTO public.profiles (user_id, email, full_name, newsletter_subscribed)
  VALUES (
    NEW.id,
    coalesce(NEW.email, ''),
    coalesce(NEW.raw_user_meta_data ->> 'full_name', ''),
    coalesce(existing_subscription_active, false)
  );

  INSERT INTO public.user_roles (user_id, role)
  VALUES (NEW.id, 'customer')
  ON CONFLICT (user_id, role) DO NOTHING;

  UPDATE public.newsletter_subscriptions
  SET user_id = NEW.id
  WHERE lower(email) = lower(coalesce(NEW.email, ''))
    AND user_id IS NULL;

  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION public.handle_new_user() FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.sync_newsletter_profile_preference()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  IF NEW.user_id IS NOT NULL THEN
    UPDATE public.profiles
    SET newsletter_subscribed = NEW.active
    WHERE user_id = NEW.user_id
      AND newsletter_subscribed IS DISTINCT FROM NEW.active;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION public.sync_newsletter_profile_preference() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS trg_sync_newsletter_profile_preference ON public.newsletter_subscriptions;
CREATE TRIGGER trg_sync_newsletter_profile_preference
  AFTER INSERT OR UPDATE OF active, user_id ON public.newsletter_subscriptions
  FOR EACH ROW
  EXECUTE FUNCTION public.sync_newsletter_profile_preference();

-- Service-only upsert used by the Edge Function. Public clients never receive
-- direct write permissions on newsletter_subscriptions.
CREATE OR REPLACE FUNCTION public.set_newsletter_subscription(
  p_email text,
  p_source text,
  p_active boolean,
  p_user_id uuid DEFAULT NULL
)
RETURNS TABLE(subscription_id uuid, welcome_needed boolean)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  normalized_email text := lower(btrim(p_email));
  normalized_source text := lower(coalesce(nullif(btrim(p_source), ''), 'website'));
BEGIN
  IF normalized_email IS NULL
    OR char_length(normalized_email) NOT BETWEEN 3 AND 254
    OR normalized_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
  THEN
    RAISE EXCEPTION 'Ongeldig e-mailadres' USING ERRCODE = '22023';
  END IF;

  IF normalized_source NOT IN ('popup', 'footer', 'website', 'profile') THEN
    normalized_source := 'website';
  END IF;

  RETURN QUERY
  INSERT INTO public.newsletter_subscriptions AS subscription (
    email, source, active, subscribed_at, unsubscribed_at, user_id
  )
  VALUES (
    normalized_email,
    normalized_source,
    p_active,
    now(),
    CASE WHEN p_active THEN NULL ELSE now() END,
    p_user_id
  )
  ON CONFLICT ((lower(email))) DO UPDATE
  SET
    active = EXCLUDED.active,
    unsubscribed_at = CASE WHEN EXCLUDED.active THEN NULL ELSE now() END,
    subscribed_at = CASE
      WHEN EXCLUDED.active AND NOT subscription.active THEN now()
      ELSE subscription.subscribed_at
    END,
    source = CASE WHEN EXCLUDED.active THEN EXCLUDED.source ELSE subscription.source END,
    user_id = COALESCE(subscription.user_id, EXCLUDED.user_id)
  RETURNING subscription.id,
    subscription.active AND subscription.welcome_email_sent_at IS NULL;
END;
$$;

REVOKE ALL ON FUNCTION public.set_newsletter_subscription(text, text, boolean, uuid)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.set_newsletter_subscription(text, text, boolean, uuid)
  TO service_role;

CREATE OR REPLACE FUNCTION public.claim_newsletter_welcome(p_subscription_id uuid)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE claimed_id uuid;
BEGIN
  UPDATE public.newsletter_subscriptions
  SET welcome_email_claimed_at = clock_timestamp()
  WHERE id = p_subscription_id
    AND active
    AND welcome_email_sent_at IS NULL
    AND (
      welcome_email_claimed_at IS NULL
      OR welcome_email_claimed_at < clock_timestamp() - interval '15 minutes'
    )
  RETURNING id INTO claimed_id;
  RETURN claimed_id IS NOT NULL;
END;
$$;

REVOKE ALL ON FUNCTION public.claim_newsletter_welcome(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.claim_newsletter_welcome(uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.claim_account_welcome(p_user_id uuid)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE claimed_id uuid;
BEGIN
  UPDATE public.profiles
  SET account_welcome_email_claimed_at = clock_timestamp()
  WHERE user_id = p_user_id
    AND account_welcome_email_sent_at IS NULL
    AND (
      account_welcome_email_claimed_at IS NULL
      OR account_welcome_email_claimed_at < clock_timestamp() - interval '15 minutes'
    )
  RETURNING id INTO claimed_id;
  RETURN claimed_id IS NOT NULL;
END;
$$;

REVOKE ALL ON FUNCTION public.claim_account_welcome(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.claim_account_welcome(uuid) TO service_role;

CREATE TABLE IF NOT EXISTS public.email_campaigns (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  template_kind text NOT NULL,
  change_type text,
  audience text NOT NULL,
  subject text NOT NULL,
  body text NOT NULL,
  status text NOT NULL DEFAULT 'sending',
  recipient_count integer NOT NULL DEFAULT 0,
  sent_count integer NOT NULL DEFAULT 0,
  failed_count integer NOT NULL DEFAULT 0,
  error_message text,
  created_at timestamptz NOT NULL DEFAULT now(),
  sent_at timestamptz,
  CONSTRAINT email_campaigns_template_kind_check
    CHECK (template_kind IN ('color', 'material', 'article', 'custom')),
  CONSTRAINT email_campaigns_change_type_check
    CHECK (change_type IS NULL OR change_type IN ('new', 'removed')),
  CONSTRAINT email_campaigns_audience_check
    CHECK (audience IN ('newsletter', 'all_customers')),
  CONSTRAINT email_campaigns_status_check
    CHECK (status IN ('sending', 'sent', 'partial', 'failed')),
  CONSTRAINT email_campaigns_counts_nonnegative
    CHECK (recipient_count >= 0 AND sent_count >= 0 AND failed_count >= 0)
);

ALTER TABLE public.email_campaigns ENABLE ROW LEVEL SECURITY;

CREATE INDEX IF NOT EXISTS email_campaigns_created_by_idx
  ON public.email_campaigns (created_by);

DROP POLICY IF EXISTS "Admins can view email campaigns" ON public.email_campaigns;
CREATE POLICY "Admins can view email campaigns"
  ON public.email_campaigns
  FOR SELECT
  TO authenticated
  USING (public.has_role((select auth.uid()), 'admin'));

REVOKE ALL ON TABLE public.email_campaigns FROM anon, authenticated;
GRANT SELECT ON TABLE public.email_campaigns TO authenticated;
GRANT ALL ON TABLE public.email_campaigns TO service_role;

-- A customer can claim an unlinked admin-created order only when both the
-- high-entropy order token and the authenticated account email match.
CREATE OR REPLACE FUNCTION public.claim_order_to_account(p_token text)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  requester_id uuid := auth.uid();
  requester_email text;
  current_owner uuid;
  order_email text;
BEGIN
  IF requester_id IS NULL THEN
    RAISE EXCEPTION 'U moet ingelogd zijn' USING ERRCODE = '42501';
  END IF;
  IF p_token IS NULL OR char_length(p_token) < 32 THEN
    RAISE EXCEPTION 'Ongeldige bestellink' USING ERRCODE = '22023';
  END IF;

  SELECT lower(email) INTO requester_email
  FROM auth.users
  WHERE id = requester_id;

  SELECT user_id, lower(customer_email)
  INTO current_owner, order_email
  FROM public.orders
  WHERE customer_order_token = p_token
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN false;
  END IF;
  IF current_owner = requester_id THEN
    RETURN true;
  END IF;
  IF current_owner IS NOT NULL THEN
    RAISE EXCEPTION 'Deze bestelling is al aan een ander account gekoppeld' USING ERRCODE = '23505';
  END IF;
  IF requester_email IS NULL OR requester_email <> order_email THEN
    RAISE EXCEPTION 'Log in met hetzelfde e-mailadres als op de bestelling' USING ERRCODE = '42501';
  END IF;

  UPDATE public.orders
  SET user_id = requester_id
  WHERE customer_order_token = p_token
    AND user_id IS NULL;

  RETURN FOUND;
END;
$$;

REVOKE ALL ON FUNCTION public.claim_order_to_account(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.claim_order_to_account(text) TO authenticated;

-- Harden the existing profile update policy with an explicit ownership check.
DROP POLICY IF EXISTS "Users can update own profile" ON public.profiles;
CREATE POLICY "Users can update own profile"
  ON public.profiles
  FOR UPDATE
  TO authenticated
  USING ((select auth.uid()) = user_id)
  WITH CHECK ((select auth.uid()) = user_id);

ALTER TABLE public.discount_codes
  ADD COLUMN IF NOT EXISTS is_referral boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS owner_email text,
  ADD COLUMN IF NOT EXISTS owner_name text,
  ADD COLUMN IF NOT EXISTS reward_percentage numeric,
  ADD COLUMN IF NOT EXISTS parent_code_id uuid REFERENCES public.discount_codes(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS assigned_to_email text;

CREATE INDEX IF NOT EXISTS discount_codes_assigned_to_email_idx ON public.discount_codes(assigned_to_email);
CREATE INDEX IF NOT EXISTS discount_codes_owner_email_idx ON public.discount_codes(owner_email);

CREATE TABLE public.filament_colors (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  material text NOT NULL,
  hex text NOT NULL DEFAULT '#808080',
  photos text[] NOT NULL DEFAULT '{}',
  description text NOT NULL DEFAULT '',
  sort_order int NOT NULL DEFAULT 0,
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

GRANT SELECT ON public.filament_colors TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.filament_colors TO authenticated;
GRANT ALL ON public.filament_colors TO service_role;

ALTER TABLE public.filament_colors ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Anyone can view active colors" ON public.filament_colors
  FOR SELECT USING (active = true OR public.has_role(auth.uid(), 'admin'));

CREATE POLICY "Admins can manage colors" ON public.filament_colors
  FOR ALL TO authenticated
  USING (public.has_role(auth.uid(), 'admin'))
  WITH CHECK (public.has_role(auth.uid(), 'admin'));

CREATE TABLE public.product_color_availability (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,
  color_id uuid NOT NULL REFERENCES public.filament_colors(id) ON DELETE CASCADE,
  available boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (product_id, color_id)
);

GRANT SELECT ON public.product_color_availability TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.product_color_availability TO authenticated;
GRANT ALL ON public.product_color_availability TO service_role;

ALTER TABLE public.product_color_availability ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Anyone can view product color availability" ON public.product_color_availability
  FOR SELECT USING (true);

CREATE POLICY "Admins can manage product color availability" ON public.product_color_availability
  FOR ALL TO authenticated
  USING (public.has_role(auth.uid(), 'admin'))
  WITH CHECK (public.has_role(auth.uid(), 'admin'));

CREATE TRIGGER trg_filament_colors_updated_at
  BEFORE UPDATE ON public.filament_colors
  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at();

CREATE TRIGGER trg_product_color_availability_updated_at
  BEFORE UPDATE ON public.product_color_availability
  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at();

CREATE INDEX filament_colors_material_idx ON public.filament_colors(material);
CREATE INDEX pca_product_idx ON public.product_color_availability(product_id);
CREATE INDEX pca_color_idx ON public.product_color_availability(color_id);

-- 1. Product categories
CREATE TABLE public.product_categories (
  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  name text NOT NULL,
  sort_order integer NOT NULL DEFAULT 0,
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT ON public.product_categories TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.product_categories TO authenticated;
GRANT ALL ON public.product_categories TO service_role;
ALTER TABLE public.product_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Anyone can view active categories" ON public.product_categories FOR SELECT USING (active OR public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins manage categories" ON public.product_categories FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE TRIGGER trg_product_categories_updated_at BEFORE UPDATE ON public.product_categories FOR EACH ROW EXECUTE FUNCTION public.update_updated_at();

-- 2. Products: category, fixed material, configurable custom fields
ALTER TABLE public.products
  ADD COLUMN IF NOT EXISTS category_id uuid REFERENCES public.product_categories(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS material_fixed boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS multicolor_allowed boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS custom_fields jsonb NOT NULL DEFAULT '[]'::jsonb;

-- 3. Order link visit tracking (admin visibility)
ALTER TABLE public.orders
  ADD COLUMN IF NOT EXISTS link_first_viewed_at timestamptz,
  ADD COLUMN IF NOT EXISTS link_last_viewed_at timestamptz,
  ADD COLUMN IF NOT EXISTS link_view_count integer NOT NULL DEFAULT 0;

-- 4. Newsletter subscribers
CREATE TABLE public.newsletter_subscribers (
  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  email text NOT NULL UNIQUE,
  name text,
  active boolean NOT NULL DEFAULT true,
  source text NOT NULL DEFAULT 'website',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
GRANT INSERT ON public.newsletter_subscribers TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.newsletter_subscribers TO authenticated;
GRANT ALL ON public.newsletter_subscribers TO service_role;
ALTER TABLE public.newsletter_subscribers ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Anyone can subscribe" ON public.newsletter_subscribers FOR INSERT TO anon, authenticated WITH CHECK (true);
CREATE POLICY "Admins can view subscribers" ON public.newsletter_subscribers FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins can manage subscribers" ON public.newsletter_subscribers FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins can delete subscribers" ON public.newsletter_subscribers FOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE TRIGGER trg_newsletter_updated_at BEFORE UPDATE ON public.newsletter_subscribers FOR EACH ROW EXECUTE FUNCTION public.update_updated_at();

-- 5. Public read access to product/color photos in the private "orders" bucket
DROP POLICY IF EXISTS "Public read product and color photos" ON storage.objects;
CREATE POLICY "Public read product and color photos" ON storage.objects FOR SELECT TO anon, authenticated
USING (bucket_id = 'orders' AND (name LIKE 'products/%' OR name LIKE 'colors/%'));

GRANT SELECT, INSERT, UPDATE, DELETE ON public.newsletter_subscribers TO authenticated;
GRANT INSERT ON public.newsletter_subscribers TO anon;
GRANT ALL ON public.newsletter_subscribers TO service_role;

DROP POLICY IF EXISTS "Anyone can view active colors" ON public.filament_colors;
DROP POLICY IF EXISTS "Anyone can view colors" ON public.filament_colors;

CREATE POLICY "Anyone can view colors" ON public.filament_colors
  FOR SELECT
  TO anon, authenticated
  USING (true);

-- Complete the relational product catalogue and support image/video media.
-- Existing products, colors and legacy image URLs are preserved.

ALTER TABLE public.product_categories
  ADD COLUMN IF NOT EXISTS description text NOT NULL DEFAULT '';

ALTER TABLE public.products
  ADD COLUMN IF NOT EXISTS material_mode text NOT NULL DEFAULT 'selected',
  ADD COLUMN IF NOT EXISTS color_selection_mode text NOT NULL DEFAULT 'single',
  ADD COLUMN IF NOT EXISTS color_required boolean NOT NULL DEFAULT true,
  ADD COLUMN IF NOT EXISTS colors_configured boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS max_colors integer NOT NULL DEFAULT 1;

UPDATE public.products
SET material_mode = CASE
  WHEN material_fixed THEN 'fixed'
  WHEN cardinality(materials) = 0 THEN 'all'
  ELSE 'selected'
END
WHERE material_mode = 'selected';

UPDATE public.products
SET color_selection_mode = 'multiple',
    max_colors = GREATEST(max_colors, 2)
WHERE multicolor_allowed;

ALTER TABLE public.products DROP CONSTRAINT IF EXISTS products_material_mode_check;
ALTER TABLE public.products ADD CONSTRAINT products_material_mode_check
  CHECK (material_mode IN ('fixed', 'selected', 'all'));
ALTER TABLE public.products DROP CONSTRAINT IF EXISTS products_color_selection_mode_check;
ALTER TABLE public.products ADD CONSTRAINT products_color_selection_mode_check
  CHECK (color_selection_mode IN ('single', 'multiple'));
ALTER TABLE public.products DROP CONSTRAINT IF EXISTS products_max_colors_check;
ALTER TABLE public.products ADD CONSTRAINT products_max_colors_check
  CHECK (max_colors BETWEEN 1 AND 12);

CREATE TABLE IF NOT EXISTS public.product_images (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,
  storage_path text NOT NULL,
  alt_text text NOT NULL DEFAULT '',
  media_type text NOT NULL DEFAULT 'image',
  sort_order integer NOT NULL DEFAULT 0,
  is_primary boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.product_images
  ADD COLUMN IF NOT EXISTS storage_path text,
  ADD COLUMN IF NOT EXISTS alt_text text NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS media_type text NOT NULL DEFAULT 'image',
  ADD COLUMN IF NOT EXISTS sort_order integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS is_primary boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'product_images' AND column_name = 'url'
  ) THEN
    EXECUTE 'UPDATE public.product_images SET storage_path = COALESCE(storage_path, url)';
    EXECUTE 'ALTER TABLE public.product_images ALTER COLUMN url DROP NOT NULL';
  END IF;
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'product_images' AND column_name = 'is_main'
  ) THEN
    EXECUTE 'UPDATE public.product_images SET is_primary = COALESCE(is_main, false) WHERE NOT is_primary';
  END IF;
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'product_images' AND column_name = 'order'
  ) THEN
    EXECUTE 'UPDATE public.product_images SET sort_order = COALESCE("order", 0) WHERE sort_order = 0';
  END IF;
END
$$;

UPDATE public.product_images
SET media_type = 'video'
WHERE lower(COALESCE(storage_path, '')) ~ '\.(mp4|webm|mov|m4v)(\?.*)?$';

ALTER TABLE public.product_images
  ALTER COLUMN product_id SET NOT NULL,
  ALTER COLUMN storage_path SET NOT NULL,
  ALTER COLUMN created_at SET DEFAULT now(),
  ALTER COLUMN created_at SET NOT NULL;
ALTER TABLE public.product_images DROP CONSTRAINT IF EXISTS product_images_media_type_check;
ALTER TABLE public.product_images ADD CONSTRAINT product_images_media_type_check
  CHECK (media_type IN ('image', 'video'));

CREATE UNIQUE INDEX IF NOT EXISTS product_images_product_storage_path_idx
  ON public.product_images (product_id, storage_path);
CREATE UNIQUE INDEX IF NOT EXISTS product_images_one_primary_idx
  ON public.product_images (product_id) WHERE is_primary;
CREATE INDEX IF NOT EXISTS product_images_product_sort_idx
  ON public.product_images (product_id, sort_order);

INSERT INTO public.product_images (product_id, storage_path, media_type, sort_order, is_primary)
SELECT
  product.id,
  media.storage_path,
  CASE WHEN lower(media.storage_path) ~ '\.(mp4|webm|mov|m4v)(\?.*)?$' THEN 'video' ELSE 'image' END,
  media.ordinality - 1,
  media.ordinality = 1
FROM public.products product
CROSS JOIN LATERAL unnest(COALESCE(product.photos, '{}'::text[]))
  WITH ORDINALITY AS media(storage_path, ordinality)
WHERE media.storage_path <> ''
ON CONFLICT (product_id, storage_path) DO NOTHING;

CREATE TABLE IF NOT EXISTS public.product_options (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,
  type text NOT NULL DEFAULT 'text',
  label text NOT NULL,
  description text NOT NULL DEFAULT '',
  required boolean NOT NULL DEFAULT false,
  choices jsonb NOT NULL DEFAULT '[]'::jsonb,
  max_length integer,
  sort_order integer NOT NULL DEFAULT 0,
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT product_options_type_check CHECK (type IN ('text', 'textarea', 'select', 'radio', 'checkbox', 'photo')),
  CONSTRAINT product_options_choices_array_check CHECK (jsonb_typeof(choices) = 'array'),
  CONSTRAINT product_options_max_length_check CHECK (max_length IS NULL OR max_length BETWEEN 1 AND 5000)
);

CREATE INDEX IF NOT EXISTS product_options_product_sort_idx
  ON public.product_options (product_id, sort_order);

INSERT INTO public.product_options (product_id, type, label, description, required, choices, max_length, sort_order)
SELECT
  product.id,
  CASE WHEN field.value->>'type' IN ('text', 'textarea', 'select', 'radio', 'checkbox', 'photo')
    THEN field.value->>'type' ELSE 'text' END,
  COALESCE(NULLIF(field.value->>'label', ''), 'Extra keuze'),
  COALESCE(field.value->>'help', ''),
  lower(COALESCE(field.value->>'required', 'false')) = 'true',
  CASE WHEN jsonb_typeof(field.value->'choices') = 'array' THEN field.value->'choices' ELSE '[]'::jsonb END,
  CASE WHEN COALESCE(field.value->>'maxLength', '') ~ '^[0-9]+$'
    THEN LEAST(5000::numeric, GREATEST(1::numeric, (field.value->>'maxLength')::numeric))::integer
    ELSE NULL END,
  field.ordinality - 1
FROM public.products product
CROSS JOIN LATERAL jsonb_array_elements(
  CASE WHEN jsonb_typeof(COALESCE(product.custom_fields, '[]'::jsonb)) = 'array'
    THEN COALESCE(product.custom_fields, '[]'::jsonb) ELSE '[]'::jsonb END
) WITH ORDINALITY AS field(value, ordinality)
WHERE NOT EXISTS (
  SELECT 1 FROM public.product_options existing WHERE existing.product_id = product.id
);

